select 
  from builder.adk_builder_business_document_revision
 where project_id = #{projectId}
   and kind = #{kind}
 order by revision_no desc

select 
  from builder.adk_builder_business_document_revision
 where project_id = #{projectId}
   and kind = #{kind}
   and revision_no = #{revisionNo}

select coalesce(max(revision_no), 0) + 1
  from builder.adk_builder_business_document_revision
 where project_id = #{projectId}
   and kind = #{kind}
